import assert from "node:assert/strict";
import { runSteps } from "./pipeline.mjs";

const ids = ["alpha", "beta", "gamma", "delta"];
const steps = ids.map((id, i) => ({
  id,
  // Random delays: completion order differs from input order run to run.
  ms: 5 + Math.floor(Math.random() * 40),
  payload: `p${i}`,
}));

const results = await runSteps(steps);

const expected = ids.map((id, i) => `${id}:p${i}`);
assert.deepEqual(results, expected);

console.log("OK");
